begin;
insert into public.db_categories(parent_id,code,name,department_id,restricted,active,sort_order) values (null,'anh_video','Ảnh, video',null,false,true,60) on conflict (code) do update set name=excluded.name,parent_id=null,department_id=null,restricted=false,active=true,sort_order=excluded.sort_order,updated_at=now();
insert into public.db_record_types(category_id,code,name,active,sort_order) select c.id,'thu_vien_anh_video','Ảnh, video',true,10 from public.db_categories c where c.code='anh_video' on conflict (code) do update set category_id=excluded.category_id,name=excluded.name,active=true,sort_order=excluded.sort_order,updated_at=now();
do $guard$ begin if exists (select 1 from public.db_record_types t where t.code in ('kho_anh_video','ngoai_ngu_anh_video_multimedia') and exists (select 1 from public.db_records r where r.record_type_id=t.id and r.status <> 'deleted')) then raise exception 'Cannot deactivate media record types with non-deleted records'; end if; end $guard$;
with source as (select f.id,f.search_config,f.display_config,f.created_by from public.db_form_definitions f join public.db_record_types t on t.id=f.record_type_id where t.code='kho_anh_video' and f.status='published' order by f.version desc limit 1), target_type as (select id from public.db_record_types where code='thu_vien_anh_video'), new_form as (insert into public.db_form_definitions(record_type_id,version,status,search_config,display_config,created_by) select target_type.id,coalesce((select max(version)+1 from public.db_form_definitions f where f.record_type_id=target_type.id),1),'published',source.search_config,source.display_config,source.created_by from source cross join target_type where not exists (select 1 from public.db_form_definitions f where f.record_type_id=target_type.id and f.status='published') returning id) insert into public.db_form_fields(form_definition_id,field_key,label,data_type,required,searchable,options,validation,sort_order,hidden) select nf.id,ff.field_key,ff.label,ff.data_type,ff.required,ff.searchable,ff.options,ff.validation,ff.sort_order,ff.hidden from new_form nf join source s on true join public.db_form_fields ff on ff.form_definition_id=s.id;
update public.db_record_types set active=false,updated_at=now() where code in ('kho_anh_video','ngoai_ngu_anh_video_multimedia');
do $assert$ declare n integer; f integer; begin select count(*) into n from public.db_categories where code='anh_video' and active and parent_id is null and department_id is null and not restricted and sort_order=60; if n<>1 then raise exception 'anh_video category assertion failed'; end if; select count(*) into n from public.db_record_types where code='thu_vien_anh_video' and active; if n<>1 then raise exception 'thu_vien_anh_video type assertion failed'; end if; select count(*) into n from public.db_form_definitions d join public.db_record_types t on t.id=d.record_type_id where t.code='thu_vien_anh_video' and d.status='published'; if n<>1 then raise exception 'media published form count invalid'; end if; select count(*) into f from public.db_form_definitions d join public.db_record_types t on t.id=d.record_type_id join public.db_form_fields x on x.form_definition_id=d.id where t.code='thu_vien_anh_video' and d.status='published' and x.field_key in ('title','status','record_code'); if f<>3 then raise exception 'media form required fields assertion failed'; end if; if exists (select 1 from public.db_record_types where code in ('kho_anh_video','ngoai_ngu_anh_video_multimedia') and active) then raise exception 'old media types still active'; end if; end $assert$;
commit;
